import * as pdfjs from './vendor/pdf.mjs';
pdfjs.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.mjs';
const BASE='https://www.cettong.cn/library/cet6/2025_06_1/';
const PDF=BASE+'test.pdf', AUDIO=BASE+'listening.mp3', SOLUTION=BASE+'answer.pdf';
const KEY='cet6-baseline-202506-1-v1';
const crops={0:{1:[0,195]},1:{1:[195,841.92],3:[0,210]},2:{3:[211,841.92],8:[0,115]},3:{8:[120,841.92]}};
const inkKey=()=>state.stage+':'+page;
const stages=[{name:'写作',minutes:30,pages:[1],start:0,end:0},{name:'听力',minutes:30,pages:[1,2,3],start:1,end:25},{name:'阅读',minutes:40,pages:[3,4,5,6,7,8],start:26,end:55},{name:'翻译',minutes:30,pages:[8],start:0,end:0}];
const answers='C B D A A D C D C B A C C B B D A B A D C D A D B J B L F A D C E G O G C I D A L F H B K C A B B C D A D C B'.split(' ');
const $=id=>document.getElementById(id);
const fresh=()=>({version:1,paper:'2025-06-1',status:'ready',stage:0,answers:{},guesses:{},writing:'',translation:'',ink:{},stageLog:[],audioPosition:0,audioStarted:false,audioEnded:false,interruptions:[],reflection:''});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||fresh()}catch{state=fresh()}
let zoom=100;
$('zoomIn').onclick=()=>{zoom=Math.min(250,zoom+25);$('pageWrap').style.width=zoom+'%'};
$('zoomOut').onclick=()=>{zoom=Math.max(100,zoom-25);$('pageWrap').style.width=zoom+'%'};
let pdf, audioURL, page=1, tool='hand', renderTask, renderSeq=0, stroke=null, sampleTimer, busy=false;
const audio=new Audio();audio.preload='auto';
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').hidden=true,3500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saveStatus').textContent='已自动保存 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}catch{$('saveStatus').textContent='浏览器保存失败，请立即导出答卷';toast('保存空间不足，请用右上角导出答卷备份。')}}
function exportState(){const data={...state,exportedAt:new Date().toISOString(),resources:{paper:PDF,audio:AUDIO,solution:state.status==='submitted'?SOLUTION:undefined}};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='CET6-摸底答卷-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
$('export').onclick=exportState;
function show(view){['welcome','exam','results'].forEach(x=>$(x).hidden=x!==view)}
async function loadResources(){
 $('resourceStatus').textContent='正在加载完整试卷与原始听力，请稍候…';$('retry').hidden=true;
 try{const out=await Promise.all([pdfjs.getDocument({url:PDF}).promise,fetch(AUDIO).then(r=>{if(!r.ok)throw Error('音频响应 '+r.status);return r.blob()})]);pdf=out[0];if(pdf.numPages<8)throw Error('试卷页数不完整');if(out[1].size<1000000)throw Error('听力文件不完整');audioURL=URL.createObjectURL(new Blob([out[1]],{type:'audio/mp4'}));audio.src=audioURL;await new Promise((ok,fail)=>{if(audio.readyState>=1)return ok();audio.onloadedmetadata=ok;audio.onerror=()=>fail(Error('浏览器无法读取音频'));setTimeout(()=>fail(Error('音频元数据读取超时')),15000)});$('resourceStatus').textContent='✓ 试卷8页已就绪 · 原始听力 '+Math.floor(audio.duration/60)+':'+String(Math.floor(audio.duration%60)).padStart(2,'0')+' · 原卷末尾答案页不在考试中展示';$('sample').disabled=false;checkStart();if(state.status==='active'){showExam();if(state.stage===1&&!state.audioEnded){$('recoverAudio').hidden=false;$('audioStatus').textContent='刷新后请继续播放，录音位置已保存';}}}catch(e){$('resourceStatus').textContent='资料加载失败：'+e.message+'。请检查网络后重试。';$('retry').hidden=false;}
}
$('retry').onclick=loadResources;
function checkStart(){$('start').disabled=!pdf||!audioURL||!$('soundOK').checked}
$('soundOK').onchange=checkStart;
$('sample').onclick=async()=>{clearTimeout(sampleTimer);audio.pause();audio.currentTime=0;try{await audio.play();$('sample').textContent='正在试听开场提示…';sampleTimer=setTimeout(()=>{audio.pause();audio.currentTime=0;$('sample').textContent='再次试听开场提示（8秒）'},8000)}catch{toast('播放未成功，请点击试听重试')}};
$('start').onclick=()=>{clearTimeout(sampleTimer);audio.pause();audio.currentTime=0;state.status='active';state.startedAt=Date.now();state.stage=0;state.deadline=Date.now()+1800000;state.stageStartedAt=Date.now();save();showExam()};
function showExam(){show('exam');const s=stages[state.stage];page=s.pages[0];$('stageTitle').textContent=s.name;$('stages').innerHTML=stages.map((x,i)=>`<span class="${i===state.stage?'current':i<state.stage?'done':''}">${i<state.stage?'✓ ':''}${i+1}. ${x.name}</span>`).join('');$('audioPanel').hidden=state.stage!==1;$('notice').textContent=state.stage===1?'进入听力后请立即点击播放。录音按原速播放一遍；声音故障会被记录，请如实反馈。':'';$('playAudio').hidden=state.audioStarted;$('recoverAudio').hidden=state.audioStarted&&!state.audioEnded&&audio.paused;$('finishStage').textContent=state.stage===3?'提交全部答卷 →':'完成本部分 →';renderAnswerArea();renderPage();tick();}
function renderAnswerArea(){const s=stages[state.stage];$('answerTitle').textContent=s.name+'答题区';const box=$('answerArea');box.replaceChildren();if(state.stage===0||state.stage===3){const field=state.stage===0?'writing':'translation';const p=document.createElement('p');p.className='fine';p.textContent='题目见左侧原卷。独立完成，不使用翻译或词典。';const t=document.createElement('textarea');t.id='response';t.setAttribute('aria-label',s.name+'答案');t.placeholder='在此输入英文答案…';t.value=state[field];const count=document.createElement('p');count.className='fine';const update=()=>{const n=t.value.trim().match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g)?.length||0;count.textContent=n+' words'+(field==='writing'?' / 要求150–200词':'');};t.oninput=()=>{state[field]=t.value;save();update()};box.append(p,t,count);update();return;}
 for(let n=s.start;n<=s.end;n++){if([1,9,16,26,36,46].includes(n)){const p=document.createElement('div');p.className='groupLabel';p.textContent=({1:'长对话 · 1–8',9:'听力篇章 · 9–15',16:'讲话与讲座 · 16–25',26:'选词填空 · 26–35',36:'长篇匹配 · 36–45',46:'仔细阅读 · 46–55'})[n];box.append(p)}const row=document.createElement('div');row.className='qrow';row.dataset.q=n;row.innerHTML=`<div class="qhead"><b>${n.toString().padStart(2,'0')}</b><label><input type="checkbox" ${state.guesses[n]?'checked':''}> 猜的／不确定</label></div>`;row.querySelector('input').onchange=e=>{state.guesses[n]=e.target.checked;save()};if(n>=26&&n<=45){const sel=document.createElement('select');sel.setAttribute('aria-label','第'+n+'题答案');sel.innerHTML='<option value="">未作答</option>'+'ABCDEFGHIJKLMNO'.slice(0,n<=35?15:14).split('').map(k=>`<option value="${k}">${k}</option>`).join('');sel.value=state.answers[n]||'';sel.onchange=()=>{state.answers[n]=sel.value;save()};row.append(sel)}else{const choices=document.createElement('div');choices.className='choices';'ABCD'.split('').forEach(k=>{const b=document.createElement('button');b.textContent=k;b.setAttribute('aria-label','第'+n+'题选'+k);b.classList.toggle('chosen',state.answers[n]===k);b.onclick=()=>{state.answers[n]=k;choices.querySelectorAll('button').forEach(x=>x.classList.toggle('chosen',x===b));save()};choices.append(b)});row.append(choices)}box.append(row);}}
async function renderPage(){if(!pdf)return;const seq=++renderSeq;if(renderTask)renderTask.cancel();$('pageLabel').textContent='第 '+page+' / 8 页';const s=stages[state.stage];$('prev').disabled=page===s.pages[0];$('next').disabled=page===s.pages.at(-1);try{const p=await pdf.getPage(page);if(seq!==renderSeq)return;const v=p.getViewport({scale:1.8});const crop=state.status==='submitted'?[0,841.92]:(crops[state.stage]?.[page]||[0,841.92]);const c=$('paperCanvas');c.width=v.width;c.height=(crop[1]-crop[0])*1.8;renderTask=p.render({canvasContext:c.getContext('2d'),viewport:v,transform:[1,0,0,1,0,-crop[0]*1.8]});await renderTask.promise;if(seq!==renderSeq)return;renderTask=null;$('ink').setAttribute('viewBox',`0 0 1000 ${1000*c.height/v.width}`);drawInk();$('paperScroller').scrollTop=0;$('paperError').hidden=true}catch(e){if(e.name!=='RenderingCancelledException'){$('paperError').hidden=false;$('paperError').textContent='试卷显示失败，请刷新恢复。'+e.message}}}
$('prev').onclick=()=>{const a=stages[state.stage].pages,i=a.indexOf(page);if(i>0){page=a[i-1];renderPage()}};$('next').onclick=()=>{const a=stages[state.stage].pages,i=a.indexOf(page);if(i<a.length-1){page=a[i+1];renderPage()}};
function drawInk(){const svg=$('ink');svg.replaceChildren();for(const st of (state.status==='submitted'?Object.entries(state.ink).filter(([k])=>k.endsWith(':'+page)).flatMap(([k,ss])=>ss.map(st=>({...st,points:st.points.map(q=>[q[0],q[1]+(crops[Number(k.split(':')[0])]?.[page]?.[0]||0)/595.32*1000])}))):(state.ink[inkKey()]||[]))){const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',st.points.map((q,i)=>(i?'L':'M')+q.join(',')).join(' '));p.setAttribute('stroke',st.tool==='marker'?'#f3c829':'#d25139');p.setAttribute('stroke-width',st.tool==='marker'?'15':'2.5');p.setAttribute('opacity',st.tool==='marker'?'.35':'.9');p.style.pointerEvents='none';svg.append(p)}}
['hand','marker','pen','eraser'].forEach(x=>$(x).onclick=()=>{tool=x;['hand','marker','pen','eraser'].forEach(t=>$(t).classList.toggle('active',t===x));$('ink').classList.toggle('draw',x!=='hand')});
function point(e){const r=$('ink').getBoundingClientRect();return [Math.round((e.clientX-r.left)/r.width*10000)/10,Math.round((e.clientY-r.top)/r.width*10000)/10]}
$('ink').onpointerdown=e=>{if(tool==='hand'||state.status==='submitted')return;e.preventDefault();$('ink').setPointerCapture(e.pointerId);const p=point(e);state.ink[inkKey()]??=[];if(tool==='eraser'){const arr=state.ink[inkKey()];const i=arr.findLastIndex(s=>s.points.some(q=>Math.hypot(q[0]-p[0],q[1]-p[1])<28));if(i>=0){arr.splice(i,1);drawInk();save()}return;}stroke={tool,points:[p,[p[0]+.1,p[1]+.1]]};state.ink[inkKey()].push(stroke);drawInk()};
$('ink').onpointermove=e=>{if(stroke){stroke.points.push(point(e));drawInk()}};function endStroke(){if(stroke){stroke=null;save()}}$('ink').onpointerup=endStroke;$('ink').onpointercancel=endStroke;$('ink').onlostpointercapture=endStroke;$('undo').onclick=()=>{state.ink[inkKey()]?.pop();drawInk();save()};
async function playListening(recover=false){if(state.status!=='active'||state.stage!==1)return;try{audio.pause();audio.currentTime=recover?state.audioPosition:0;await audio.play();state.audioStarted=true;$('playAudio').hidden=true;$('recoverAudio').hidden=true;$('audioStatus').textContent='正在播放 · 原速 · 不可回放';if(recover){state.interruptions.push({type:'audio-resume',at:Date.now(),position:state.audioPosition})}save()}catch(e){$('recoverAudio').hidden=false;$('audioStatus').textContent='播放未成功，请点击继续播放';state.interruptions.push({type:'play-failed',at:Date.now(),message:e.message});save()}}
$('playAudio').onclick=()=>playListening(false);$('recoverAudio').onclick=()=>playListening(state.audioStarted);$('volume').oninput=e=>audio.volume=Number(e.target.value);
audio.ontimeupdate=()=>{if(state.status==='active'&&state.stage===1){state.audioPosition=audio.currentTime;$('audioProgress').value=audio.currentTime/audio.duration;if(!audio.lastSave||Date.now()-audio.lastSave>2500){save();audio.lastSave=Date.now()}}};audio.onended=()=>{if(state.stage===1&&state.status==='active'){state.audioEnded=true;$('audioStatus').textContent='录音播放完毕，可检查答案后进入阅读';save()}};audio.onwaiting=()=>{if(state.stage===1&&state.status==='active'){$('audioStatus').textContent='播放暂时等待，请稍候';}};audio.onerror=()=>{if(state.stage===1&&state.status==='active'){$('audioStatus').textContent='音频故障，请恢复播放';$('recoverAudio').hidden=false;state.interruptions.push({type:'audio-error',at:Date.now()});save()}};
function ask(title,body){return new Promise(resolve=>{$('confirmTitle').textContent=title;$('confirmBody').textContent=body;const d=$('confirmDialog');d.showModal();$('acceptDialog').onclick=()=>{d.close();resolve(true)};$('cancelDialog').onclick=()=>{d.close();resolve(false)};d.oncancel=()=>resolve(false)})}
$('finishStage').onclick=async()=>{const s=stages[state.stage];const missing=s.start?Array.from({length:s.end-s.start+1},(_,i)=>i+s.start).filter(n=>!state.answers[n]).length:!(state.stage===0?state.writing:state.translation).trim();if(state.stage===1&&!state.audioEnded){toast('请听完录音再结束听力；有声音故障请用恢复播放。');return}if(await ask(state.stage===3?'确认交卷？':'确认锁定'+s.name+'？',missing?'本部分还有未作答内容。锁定后不能修改，是否仍要继续？':'锁定后不能返回修改。答案已自动保存。'))advance(false)};
function advance(expired){if(state.status!=='active'||busy)return;busy=true;const now=Date.now();state.stageLog.push({stage:stages[state.stage].name,startedAt:state.stageStartedAt,finishedAt:now,expired,elapsedSeconds:Math.round((now-state.stageStartedAt)/1000)});audio.pause();if(expired&&$('confirmDialog').open)$('confirmDialog').close();if(state.stage===3){state.status='submitted';state.submittedAt=now;delete state.deadline;save();showResults()}else{state.stage++;state.stageStartedAt=now;state.deadline=now+stages[state.stage].minutes*60000;save();showExam();if(expired)toast('上一部分时间到，答案已锁定。')}busy=false;}
function tick(){if(state.status!=='active')return;const seconds=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));$('timer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('timer').style.color=seconds<300?'#b56d2d':'';if(seconds===0&&pdf)advance(true)}setInterval(tick,1000);
function showResults(){show('results');const groups=[['听力',1,25],['选词填空',26,35],['长篇匹配',36,45],['仔细阅读',46,55]];const cards=groups.map(([name,a,b])=>{const ns=Array.from({length:b-a+1},(_,i)=>i+a);const right=ns.filter(n=>state.answers[n]===answers[n-1]).length;const guessed=ns.filter(n=>state.guesses[n]).length;return `<div class="resultCard"><span>${name}</span><b>${right} / ${ns.length}</b><span>${guessed} 题标记不确定</span></div>`}).join('');const right=answers.filter((a,i)=>state.answers[i+1]===a).length;const keys=answers.map((a,i)=>`<div class="${state.answers[i+1]===a?'':'wrong'}">${i+1}. ${state.answers[i+1]||'—'} → ${a}${state.guesses[i+1]?' ?':''}</div>`).join('');$('results').innerHTML=`<h1>模拟考试结果</h1><p>客观题答对 <b>${right} / 55</b>。各题权重不同，以上为原始正确题数，不是官方成绩。作文和翻译待人工批改。</p><div class="resultCards">${cards}</div><div class="actions"><a href="study.html" class="primary" style="text-decoration:none;border-radius:7px">下一任务：词汇训练 →</a><button id="resultExport" class="primary">导出答卷，发回聊天进行诊断</button><button id="downloadExplanation">打开完整答案详解 ↗</button><button id="reviewPaper">回看试卷与标注</button></div><p class="fine">答卷保存在当前设备和浏览器，没有自动发送给聊天。请导出JSON文件交给我；其中含作文、翻译、标注、不确定题和作答记录。</p><details open><summary>逐题核对 · 红色为错答或未答</summary><p class="fine">格式：题号 · 你的答案 → 参考答案；? 表示你标记了不确定。</p><div class="keygrid">${keys}</div></details><details><summary>完整答案详解与听力原文（20页）</summary><p>包含逐题解析、听力原文、写作与翻译参考。来源：CET通配套解析；可用上方按钮单独打开。</p><iframe title="完整答案详解" data-src="${SOLUTION}"></iframe></details><details><summary>听力原声重听</summary><audio controls preload="none" src="${audioURL||AUDIO}" style="width:100%;margin-top:20px"></audio></details><details><summary>作文与翻译原答</summary><h3>写作</h3><pre id="writingReview"></pre><h3>翻译</h3><pre id="translationReview"></pre></details><details open><summary>交卷后补充两句话</summary><p>阅读最卡在哪里？听力能听出完整句意，还是主要靠选项词汇碰运气？遇到设备问题也请记录。</p><textarea id="reflection" placeholder="例如：阅读第三篇没做完；听力第二段开始跟不上…"></textarea></details><p class="fine">真题与解析由 <a href="https://www.cettong.cn/library/cet6/2025_06_1" target="_blank" rel="noopener">CET通</a> 提供，参考答案与 <a href="https://eol.nju.edu.cn/cet6/papers/202506-1.html" target="_blank" rel="noopener">南京大学自测资料</a> 对照。题目版权归相应权利人。个人学习使用。</p>`;$('writingReview').textContent=state.writing||'未作答';$('translationReview').textContent=state.translation||'未作答';$('reflection').value=state.reflection||'';$('reflection').oninput=e=>{state.reflection=e.target.value;save()};$('resultExport').onclick=exportState;$('downloadExplanation').onclick=()=>window.open(SOLUTION,'_blank','noopener');$('reviewPaper').onclick=()=>{show('exam');$('stageTitle').textContent='试卷与标注回看';$('stages').innerHTML='<button id="backResults">← 返回结果</button>';$('backResults').onclick=showResults;$('audioPanel').hidden=true;$('notice').textContent='考后回看模式，正式答卷已锁定。';$('answerArea').replaceChildren();$('answerTitle').textContent='答卷已提交';$('finishStage').hidden=true;page=1;const original=stages[state.stage].pages;stages[state.stage].pages=[1,2,3,4,5,6,7,8];renderPage();$('backResults').onclick=()=>{stages[state.stage].pages=original;showResults()}};document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{const f=d.querySelector('iframe[data-src]');if(d.open&&f){f.src=f.dataset.src;delete f.dataset.src}}));}
window.addEventListener('pagehide',()=>{if(state.status==='active')state.interruptions.push({type:'page-hidden-or-closed',at:Date.now()});save()});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.status==='active'){state.interruptions.push({type:'tab-hidden',at:Date.now()});save()}});
if(state.status==='submitted')showResults();else if(state.status==='active'){show('exam');$('notice').textContent='正在恢复答卷并重新连接资料…';}
loadResources();
